import {
  Home,
  FolderGit2,
  BrainCircuit,
  User,
  Mail,
} from "lucide-react";

const navigation = [
  { name: "Home", href: "/", icon: Home },
  { name: "About", href: "/about", icon: User },
  { name: "Projects", href: "/projects", icon: FolderGit2 },
  { name: "Skills", href: "/skills", icon: BrainCircuit },
  { name: "Contact", href: "/contact", icon: Mail },
];

export default navigation;
